                    "profile": profile_name(profile),
                    "model": codex_body.get("model"),
                    "input_type": type(codex_body.get("input")).__name__,
                    "previous_response_id": codex_body.get("previous_response_id"),
                    "tool_count": len(codex_body.get("tools") or []),
                },
                ensure_ascii=False,
